edits.newText:
// B-015: show the glyph when the playing track isn't currently
// in view. This covers both:
//   1) the playing track's parent folder differs (outside the
//      browsed folder), and
//   2) the parent folder is the same, but the row is scrolled out
//      of the visible browser viewport.
//
// B-031 debounces the hide.
final playingParent = playingPath != null ? p.dirname(playingPath) : '';
final playingInCurrentFolder = playingPath != null &&
    playingPath.isNotEmpty &&
    playingParent == (path ?? '');

final isVisible = visibilityProbeReady.value &&
    playingInCurrentFolder &&
    playingPath != null &&
    browserController.isTrackVisible(playingPath);

final needsJump = playingPath != null &&
    playingPath.isNotEmpty &&
    (!playingInCurrentFolder || !isVisible);

final showJumpGlyph = resolveJumpGlyphVisible(needsJump);

